-- Required persistence for Modules 3-5. Safe migration intended before product-management-v3.
DO $$ BEGIN CREATE TYPE "CollectionType" AS ENUM ('MANUAL','AUTOMATIC','SEASONAL'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE "StockTransferStatus" AS ENUM ('DRAFT','IN_TRANSIT','COMPLETED','CANCELLED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE "PurchaseOrderStatus" AS ENUM ('DRAFT','ORDERED','PARTIAL','RECEIVED','CANCELLED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE TABLE IF NOT EXISTS "Brand" ("id" SERIAL PRIMARY KEY,"name" TEXT NOT NULL,"slug" TEXT NOT NULL UNIQUE,"description" TEXT,"imageUrl" TEXT,"isActive" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "Collection" ("id" SERIAL PRIMARY KEY,"name" TEXT NOT NULL,"slug" TEXT NOT NULL UNIQUE,"description" TEXT,"imageUrl" TEXT,"type" "CollectionType" NOT NULL DEFAULT 'MANUAL',"rules" JSONB,"isFeatured" BOOLEAN NOT NULL DEFAULT false,"startsAt" TIMESTAMP(3),"endsAt" TIMESTAMP(3),"isActive" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "CollectionProduct" ("collectionId" INTEGER NOT NULL,"productId" INTEGER NOT NULL,"position" INTEGER NOT NULL DEFAULT 0,PRIMARY KEY("collectionId","productId"));
CREATE TABLE IF NOT EXISTS "SearchHistory" ("id" SERIAL PRIMARY KEY,"userId" INTEGER NOT NULL,"query" TEXT NOT NULL,"searchedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS "SearchHistory_userId_searchedAt_idx" ON "SearchHistory"("userId","searchedAt");
CREATE TABLE IF NOT EXISTS "Warehouse" ("id" SERIAL PRIMARY KEY,"name" TEXT NOT NULL,"code" TEXT NOT NULL UNIQUE,"address" JSONB,"isActive" BOOLEAN NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS "WarehouseInventory" ("warehouseId" INTEGER NOT NULL,"variantId" INTEGER NOT NULL,"quantity" INTEGER NOT NULL DEFAULT 0,"reserved" INTEGER NOT NULL DEFAULT 0,PRIMARY KEY("warehouseId","variantId"));
CREATE INDEX IF NOT EXISTS "WarehouseInventory_variantId_idx" ON "WarehouseInventory"("variantId");
CREATE TABLE IF NOT EXISTS "StockTransfer" ("id" SERIAL PRIMARY KEY,"fromWarehouseId" INTEGER NOT NULL,"toWarehouseId" INTEGER NOT NULL,"status" "StockTransferStatus" NOT NULL DEFAULT 'DRAFT',"items" JSONB NOT NULL,"notes" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"completedAt" TIMESTAMP(3));
CREATE TABLE IF NOT EXISTS "Supplier" ("id" SERIAL PRIMARY KEY,"name" TEXT NOT NULL,"email" TEXT,"phone" TEXT,"gstin" TEXT,"address" JSONB);
CREATE TABLE IF NOT EXISTS "PurchaseOrder" ("id" SERIAL PRIMARY KEY,"supplierId" INTEGER NOT NULL,"status" "PurchaseOrderStatus" NOT NULL DEFAULT 'DRAFT',"items" JSONB NOT NULL,"total" DECIMAL(18,2),"expectedAt" TIMESTAMP(3),"receivedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
DO $$ BEGIN ALTER TABLE "CollectionProduct" ADD CONSTRAINT "CollectionProduct_collectionId_fkey" FOREIGN KEY("collectionId") REFERENCES "Collection"("id") ON DELETE CASCADE ON UPDATE CASCADE; EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN ALTER TABLE "CollectionProduct" ADD CONSTRAINT "CollectionProduct_productId_fkey" FOREIGN KEY("productId") REFERENCES "Product"("id") ON DELETE CASCADE ON UPDATE CASCADE; EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN ALTER TABLE "SearchHistory" ADD CONSTRAINT "SearchHistory_userId_fkey" FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE; EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN ALTER TABLE "WarehouseInventory" ADD CONSTRAINT "WarehouseInventory_warehouseId_fkey" FOREIGN KEY("warehouseId") REFERENCES "Warehouse"("id") ON DELETE CASCADE ON UPDATE CASCADE; EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN ALTER TABLE "StockTransfer" ADD CONSTRAINT "StockTransfer_fromWarehouseId_fkey" FOREIGN KEY("fromWarehouseId") REFERENCES "Warehouse"("id") ON DELETE RESTRICT ON UPDATE CASCADE; EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN ALTER TABLE "StockTransfer" ADD CONSTRAINT "StockTransfer_toWarehouseId_fkey" FOREIGN KEY("toWarehouseId") REFERENCES "Warehouse"("id") ON DELETE RESTRICT ON UPDATE CASCADE; EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN ALTER TABLE "PurchaseOrder" ADD CONSTRAINT "PurchaseOrder_supplierId_fkey" FOREIGN KEY("supplierId") REFERENCES "Supplier"("id") ON DELETE RESTRICT ON UPDATE CASCADE; EXCEPTION WHEN duplicate_object THEN NULL; END $$;
